Subject: [PATCH] PS: fix an error introduced in f10b7234e27

Else the check on i doesn't make sense

diff --git a/modules/demux/ps.c b/modules/demux/ps.c
index 0b0227529c..51361bf5b0 100644
--- a/modules/demux/ps.c
+++ b/modules/demux/ps.c
@@ -238,7 +238,6 @@ static void FindLength( demux_t *p_demux )
 {
     demux_sys_t *p_sys = p_demux->p_sys;
     int64_t i_current_pos = -1, i_size = 0, i_end = 0;
-    int i;

     if( !var_CreateGetBool( p_demux, "ps-trust-timestamps" ) )
         return;
@@ -247,7 +246,7 @@ static void FindLength( demux_t *p_demux )
     {
         p_sys->i_length = 0;
         /* Check beginning */
-        i = 0;
+        int i = 0;
         i_current_pos = stream_Tell( p_demux->s );
         while( vlc_object_alive (p_demux) && i < 40 && Demux2( p_demux, false ) > 0 ) i++;

@@ -255,13 +254,13 @@ static void FindLength( demux_t *p_demux )
         i_size = stream_Size( p_demux->s );
         i_end = __MAX( 0, __MIN( 200000, i_size ) );
         stream_Seek( p_demux->s, i_size - i_end );
-        i = 0;

-        while( vlc_object_alive (p_demux) && i < 40 && Demux2( p_demux, true ) > 0 );
+        i = 0;
+        while( vlc_object_alive (p_demux) && i < 40 && Demux2( p_demux, true ) > 0 ) i++;
         if( i_current_pos >= 0 ) stream_Seek( p_demux->s, i_current_pos );
     }

-    for( i = 0; i < PS_TK_COUNT; i++ )
+    for( int i = 0; i < PS_TK_COUNT; i++ )
     {
         ps_track_t *tk = &p_sys->tk[i];
         if( tk->i_first_pts >= 0 && tk->i_last_pts > 0 )
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the incorrect handling of the variable `i`, which was declared outside of the loop and not properly initialized or incremented within the loop. This led to a situation where the check on `i` did not make sense, potentially causing incorrect behavior in the loop logic and affecting the overall functionality of the `FindLength` function.

        Commit message:
        PS: fix an error introduced in f10b7234e27

Else the check on i doesn't make sense  

        Patch:

 static void FindLength( demux_t *p_demux )
 {
     demux_sys_t *p_sys = p_demux->p_sys;
     int64_t i_current_pos = -1, i_size = 0, i_end = 0;
-    int i;

     if( !var_CreateGetBool( p_demux, "ps-trust-timestamps" ) )
         return;

     if( p_sys->i_length == -1 ) /* First time */
     {
         p_sys->i_length = 0;
         /* Check beginning */
-        i = 0;
+        int i = 0;
         i_current_pos = stream_Tell( p_demux->s );
         while( vlc_object_alive (p_demux) && i < 40 && Demux2( p_demux, false ) > 0 ) i++;

         /* Check end */
         i_size = stream_Size( p_demux->s );
         i_end = __MAX( 0, __MIN( 200000, i_size ) );
         stream_Seek( p_demux->s, i_size - i_end );
-        i = 0;

-        while( vlc_object_alive (p_demux) && i < 40 && Demux2( p_demux, true ) > 0 );
+        i = 0;
+        while( vlc_object_alive (p_demux) && i < 40 && Demux2( p_demux, true ) > 0 ) i++;
         if( i_current_pos >= 0 ) stream_Seek( p_demux->s, i_current_pos );
     }

-    for( i = 0; i < PS_TK_COUNT; i++ )
+    for( int i = 0; i < PS_TK_COUNT; i++ )
     {
         ps_track_t *tk = &p_sys->tk[i];
         if( tk->i_first_pts >= 0 && tk->i_last_pts > 0 )
             if( tk->i_last_pts > tk->i_first_pts )
             {
                 int64_t i_length = (int64_t)tk->i_last_pts - tk->i_first_pts;
                 if( i_length > p_sys->i_length )
                 {
                     p_sys->i_length = i_length;
                     p_sys->i_time_track = i;
                     msg_Dbg( p_demux, "we found a length of: %"PRId64, p_sys->i_length );
                 }
             }
     }
 }



